{"command":"python3 - << 'PY'
import re, collections
single={}
pairs=[]
mode=0
for line in open("/tmp/order.txt"):
    if line.startswith("--- pairs"): mode=1; continue
    if mode==0:
        m=re.match(r"(\S+) (Error: .*?) CODE",line)
        if m: single[m.group(1)]=m.group(2)
    else:
        m=re.match(r"(\S+) \+ (\S+) => (Error: .*?) CODE",line)
        if m: pairs.append((m.group(1),m.group(2),m.group(3)))
# for each unordered pair determine winner if error equals one of singles
wins=collections.Counter(); losses=collections.Counter(); rel={}
for a,b,e in pairs:
    w=None
    if e==single.get(a): w=a
    elif e==single.get(b): w=b
    if w:
        other=b if w==a else a
        rel[(a,b)]=w
        wins[w]+=1; losses[other]+=1
    else:
        rel[(a,b)]="OTHER:"+e
keys=list(single)
# topological ranking by wins-losses where each unordered appears twice maybe count duplicated
score={k:0 for k in keys}
seen=set()
for (a,b),w in rel.items():
    key=tuple(sorted((a,b)))
    if key in seen or w not in keys: continue
    seen.add(key)
    other=b if w==a else a
    score[w]+=1; score[other]-=1
print("ranking by pair wins:")
for k in sorted(keys,key=lambda k:-score[k]): print(k,score[k],single[k])
# Inconsistencies where two orders of same pair give different winner
for key in sorted(seen):
    vals=sorted(set(rel.get(p,"") for p in [key,(key[1],key[0])]))
    if len(vals)>1: print("inconsistent order pair",key,vals)
PY
"}

