[package]
name = "terminal_size"
version = "0.4.3"
edition = "2021"

[lib]
path = "src/lib.rs"
EOF
cat > vendor/terminal_size/src/lib.rs <<'RS'
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: std::ffi::c_ulong, ...) -> i32;
}

pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [1, 2, 0] {
        let mut winsz = WinSize::default();
        let ret = unsafe { ioctl(fd, 0x5413, &mut winsz as *mut WinSize) };
        if ret == 0 && winsz.ws_col > 0 {
            return Some((Width(winsz.ws_col), Height(winsz.ws_row)));
        }
    }
    None
}
RS
