{"command":"cat > src/decimal.rs <<'RS'
use std::cmp::Ordering;

pub const MAX_COEFF: i128 = 79_228_162_514_264_337_593_543_950_335;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Decimal {
    pub coeff: i128, // signed
    pub scale: u32,
}

fn increment_digit_string(mut digits: String) -> String {
    let mut bytes = digits.into_bytes();
    let mut i = bytes.len();
    loop {
        if i == 0 {
            bytes.insert(0, b'1');
            break;
        }
        i -= 1;
        if bytes[i] == b'9' {
            bytes[i] = b'0';
        } else {
            bytes[i] += 1;
            break;
        }
    }
    digits = String::from_utf8(bytes).unwrap();
    digits
}

// Round a coefficient digit string (no sign, may have leading zeros) to a smaller scale.
fn round_to_scale(digits_in: &str, scale_in: u32, target_scale: u32) -> (String, u32) {
    if scale_in <= target_scale {
        return (digits_in.to_string(), scale_in);
    }
    let drop = (scale_in - target_scale) as usize;
    let digits = digits_in.trim_start_matches('0');
    if digits.is_empty() {
        return ("0".to_string(), target_scale);
    }
    if drop >= digits.len() {
        // The first dropped digit is determined by position relative to the
        // integer digit string; missing leading digits are zeroes except
        // when drop == len, in which case the most-significant digit moves
        // to the first dropped position.
        let first_dropped = if drop == digits.len() {
            digits.as_bytes()[0]
        } else {
            b'0'
        };
        let rounded = if first_dropped >= b'5' { "1".to_string() } else { "0".to_string() };
        return (rounded, target_scale);
    }
    let keep_len = digits.len() - drop;
    let mut kept = digits[..keep_len].to_string();
    let first_dropped = digits.as_bytes()[keep_len];
    if first_dropped >= b'5' {
        kept = increment_digit_string(kept);
    }
    (kept, target_scale)
}

fn coeff_from_digits(digits: &str) -> Option<i128> {
    let trimmed = digits.trim_start_matches('0');
    if trimmed.is_empty() {
        return Some(0);
    }
    // Compare against MAX as a digit string before parsing into i128.
    let max_str = "79228162514264337593543950335";
    if trimmed.len() > max_str.len() || (trimmed.len() == max_str.len() && trimmed > max_str) {
        return None;
    }
    trimmed.parse::<i128>().ok()
}

impl Decimal {
    pub fn one() -> Self { Self { coeff: 1, scale: 0 } }
    pub fn is_zero(&self) -> bool { self.coeff == 0 }

    pub fn parse(input: &str) -> Result<Self, &'static str> {
        if input.is_empty() {
            return Err("empty");
        }
        let chars: Vec<char> = input.chars().collect();
        let mut idx = 0usize;
        let mut negative = false;
        if idx < chars.len() && (chars[idx] == '+' || chars[idx] == '-') {
            negative = chars[idx] == '-';
            idx += 1;
        }
        if idx >= chars.len() {
            return Err("no digits found");
        }
        if chars[idx] == '_' {
            return Err("must start lead with a number");
        }
        let mut seen_digit = false;
        let mut seen_dot = false;
        let mut digits = String::new();
        let mut scale: u32 = 0;
        for &ch in &chars[idx..] {
            match ch {
                '0'..='9' => {
                    seen_digit = true;
                    digits.push(ch);
                    if seen_dot {
                        scale = scale.saturating_add(1);
                    }
                }
                '.' => {
                    if seen_dot {
                        return Err("two decimal points");
                    }
                    seen_dot = true;
                }
                '_' => {
                    // Digit separator; ignored by rust_decimal's parser.
                }
                _ => return Err("unknown character"),
            }
        }
        if !seen_digit {
            return Err("no digits found");
        }
        // Reduce scale to at most 28, with rounding.
        let (mut digits2, mut scale2) = round_to_scale(&digits, scale, 28);
        // Reduce precision until the coefficient fits into 96 bits, if that
        // can be done by dropping fractional digits.
        while coeff_from_digits(&digits2).is_none() {
            if scale2 == 0 {
                return Err("overflow from too many digits");
            }
            let (d, s) = round_to_scale(&digits2, scale2, scale2 - 1);
            digits2 = d;
            scale2 = s;
        }
        let mut coeff = coeff_from_digits(&digits2).ok_or("overflow from too many digits")?;
        if negative {
            coeff = -coeff;
        }
        if coeff == 0 {
            // Keep the scale (e.g. 0.00), but never keep a negative zero.
            coeff = 0;
        }
        Ok(Self { coeff, scale: scale2 })
    }

    fn aligned_coeff(self, target_scale: u32) -> Option<i128> {
        if self.scale >= target_scale {
            // Caller only aligns upwards.
            debug_assert_eq!(self.scale, target_scale);
            return Some(self.coeff);
        }
        let diff = target_scale - self.scale;
        let mut factor: i128 = 1;
        for _ in 0..diff {
            factor = factor.checked_mul(10)?;
        }
        self.coeff.checked_mul(factor)
    }

    pub fn cmp_decimal(&self, other: &Self) -> Ordering {
        let self_sign = self.coeff.signum();
        let other_sign = other.coeff.signum();
        if self_sign != other_sign {
            return self_sign.cmp(&other_sign);
        }
        if self_sign == 0 {
            return Ordering::Equal;
        }
        let target = self.scale.max(other.scale);
        let a = self.aligned_coeff(target);
        let b = other.aligned_coeff(target);
        if let (Some(a), Some(b)) = (a, b) {
            return a.cmp(&b);
        }
        // Extremely large coefficients with very different scales: compare
        // by the position of the most significant digit first.
        let digits_of = |v: i128| -> i64 {
            let mut n = v.unsigned_abs();
            let mut d = 1i64;
            while n >= 10 { n /= 10; d += 1; }
            d
        };
        let exp_a = digits_of(self.coeff) - self.scale as i64;
        let exp_b = digits_of(other.coeff) - other.scale as i64;
        if exp_a != exp_b {
            return if self_sign > 0 { exp_a.cmp(&exp_b) } else { exp_b.cmp(&exp_a) };
        }
        // Fall back to an f64 comparison for this pathological case.
        let fa = self.coeff as f64 / 10f64.powi(self.scale as i32);
        let fb = other.coeff as f64 / 10f64.powi(other.scale as i32);
        fa.partial_cmp(&fb).unwrap_or(Ordering::Equal)
    }

    pub fn add(&self, other: &Self) -> Option<Self> {
        let target = self.scale.max(other.scale);
        let a = self.aligned_coeff(target)?;
        let b = other.aligned_coeff(target)?;
        let coeff = a.checked_add(b)?;
        if coeff.unsigned_abs() > MAX_COEFF as u128 {
            return None;
        }
        Some(Self { coeff, scale: target })
    }

    // Value represented in units of 10^-common_scale.  Used for the
    // parameter-scan size calculation.
    pub fn units_at_scale(&self, common_scale: u32) -> Option<i128> {
        self.aligned_coeff(common_scale)
    }

    pub fn to_string_decimal(&self) -> String {
        if self.coeff == 0 {
            if self.scale == 0 {
                return "0".to_string();
            }
            return format!("0.{}", "0".repeat(self.scale as usize));
        }
        let negative = self.coeff < 0;
        let digits = self.coeff.unsigned_abs().to_string();
        let body = if self.scale == 0 {
            digits
        } else {
            let scale = self.scale as usize;
            let padded = if digits.len() <= scale {
                format!("{}{}", "0".repeat(scale + 1 - digits.len()), digits)
            } else {
                digits
            };
            let split = padded.len() - scale;
            format!("{}.{}", &padded[..split], &padded[split..])
        };
        if negative { format!("-{body}") } else { body }
    }
}

pub fn build_scan_values(min_s: &str, max_s: &str, step_s: Option<&str>) -> Result<Vec<String>, String> {
    let parse_wrap = |s: &str| -> Result<Decimal, String> {
        Decimal::parse(s).map_err(|e| format!("Error while parsing parameter scan arguments (Invalid decimal: {e})"))
    };
    let min = parse_wrap(min_s)?;
    let max = parse_wrap(max_s)?;
    let step = match step_s {
        Some(s) => parse_wrap(s)?,
        None => {
            let min_is_i32 = min_s.parse::<i32>().is_ok();
            let max_is_i32 = max_s.parse::<i32>().is_ok();
            if min_is_i32 && max_is_i32 {
                Decimal::one()
            } else {
                return Err("A step size is required when the range bounds are floating point numbers. The step size can be specified with the '-D/--parameter-step-size <DELTA>' parameter".to_string());
            }
        }
    };
    if step.is_zero() {
        return Err("Zero is not a valid parameter step".to_string());
    }
    if max.cmp_decimal(&min) == Ordering::Less {
        return Err("Empty parameter range".to_string());
    }
    // Size guard.
    let common_scale = min.scale.max(max.scale).max(step.scale);
    let min_u = min.units_at_scale(common_scale);
    let max_u = max.units_at_scale(common_scale);
    let step_u = step.units_at_scale(common_scale);
    match (min_u, max_u, step_u) {
        (Some(min_u), Some(max_u), Some(step_u)) => {
            if step_u <= 0 {
                return Err("Parameter range is too large".to_string());
            }
            let intervals = (max_u - min_u) / step_u;
            if intervals + 1 > 100_000 {
                return Err("Parameter range is too large".to_string());
            }
        }
        _ => {
            return Err("Parameter range is too large".to_string());
        }
    }
    let mut values = Vec::new();
    let mut current = min;
    loop {
        values.push(current.to_string_decimal());
        if current.cmp_decimal(&max) != Ordering::Less {
            break;
        }
        match current.add(&step) {
            Some(next) => {
                // Defensive: a non-advancing step should not loop forever.
                if next.cmp_decimal(&current) != Ordering::Greater {
                    break;
                }
                current = next;
            }
            None => break,
        }
        if values.len() > 100_000 {
            return Err("Parameter range is too large".to_string());
        }
    }
    Ok(values)
}
RS
"}

