fn increment_digit_string(mut digits: String) -> String {
    let mut bytes = digits.into_bytes();
    let mut i = bytes.len();
    loop {
        if i == 0 {
            bytes.insert(0, b'1');
            break;
        }
        i -= 1;
        if bytes[i] == b'9' {
            bytes[i] = b'0';
        } else {
            bytes[i] += 1;
            break;
        }
    }
    digits = String::from_utf8(bytes).unwrap();
