}

// Round a coefficient digit string (no sign, may have leading zeros) to a smaller scale.
fn round_to_scale(digits_in: &str, scale_in: u32, target_scale: u32) -> (String, u32) {
    if scale_in <= target_scale {
        return (digits_in.to_string(), scale_in);
    }
    let drop = (scale_in - target_scale) as usize;
    let digits = digits_in.trim_start_matches('0');
    if digits.is_empty() {
        return ("0".to_string(), target_scale);
