        };
        let rounded = if first_dropped >= b'5' { "1".to_string() } else { "0".to_string() };
        return (rounded, target_scale);
    }
    let keep_len = digits.len() - drop;
    let mut kept = digits[..keep_len].to_string();
    let first_dropped = digits.as_bytes()[keep_len];
    if first_dropped >= b'5' {
        kept = increment_digit_string(kept);
    }
