#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Unit {
    Microsecond,
    Millisecond,
    Second,
}

impl Unit {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "microsecond" => Some(Self::Microsecond),
            "millisecond" => Some(Self::Millisecond),
            "second" => Some(Self::Second),
            _ => None,
        }
    }
    pub fn short(&self) -> &'static str {
        match self {
            Self::Microsecond => "µs",
            Self::Millisecond => "ms",
            Self::Second => "s",
        }
    }
}

pub fn unit_from_value(value_seconds: f64) -> Unit {
    if value_seconds >= 1.0 {
        Unit::Second
    } else if value_seconds >= 0.001 {
        Unit::Millisecond
    } else {
        Unit::Microsecond
    }
}

pub fn format_duration_value(value_seconds: f64, unit: Unit) -> String {
    match unit {
        Unit::Second => format!("{:.3}", value_seconds),
        Unit::Millisecond => format!("{:.1}", value_seconds * 1e3),
        Unit::Microsecond => format!("{:.1}", value_seconds * 1e6),
    }
}

pub fn format_duration_with_unit(value_seconds: f64, unit: Unit) -> String {
    format!("{} {}", format_duration_value(value_seconds, unit), unit.short())
}

pub fn format_duration(value_seconds: f64, unit: Option<Unit>) -> String {
    let unit = unit.unwrap_or_else(|| unit_from_value(value_seconds));
    format_duration_with_unit(value_seconds, unit)
}
