#[derive(Debug)]
pub struct MissingClosingQuote;

#[derive(Clone, Copy, PartialEq, Eq)]
enum State { Normal, Single, Double }

pub fn split(input: &str) -> Result<Vec<String>, MissingClosingQuote> {
    let mut words: Vec<String> = Vec::new();
    let mut current: Option<String> = None;
    let mut state = State::Normal;
    let mut chars = input.chars().peekable();
    while let Some(ch) = chars.next() {
        match state {
            State::Normal => {
                if ch.is_whitespace() {
                    if let Some(w) = current.take() {
                        words.push(w);
                    }
                } else if ch == '#' && current.is_none() {
                    break;
                } else if ch == '\'' {
                    current.get_or_insert_with(String::new);
                    state = State::Single;
                } else if ch == '"' {
                    current.get_or_insert_with(String::new);
                    state = State::Double;
                } else if ch == '\\' {
                    let word = current.get_or_insert_with(String::new);
                    match chars.next() {
                        Some('\n') => {}
                        Some(next) => word.push(next),
                        None => word.push('\\'),
                    }
                } else {
                    current.get_or_insert_with(String::new).push(ch);
                }
            }
            State::Single => {
                if ch == '\'' {
                    state = State::Normal;
                } else {
                    current.get_or_insert_with(String::new).push(ch);
                }
            }
            State::Double => {
                if ch == '"' {
                    state = State::Normal;
                } else if ch == '\\' {
                    match chars.peek().copied() {
                        Some(next) if matches!(next, '$' | '`' | '"' | '\\') => {
                            chars.next();
                            current.get_or_insert_with(String::new).push(next);
                        }
                        Some('\n') => {
                            chars.next();
                        }
                        _ => {
                            current.get_or_insert_with(String::new).push('\\');
                        }
                    }
                } else {
                    current.get_or_insert_with(String::new).push(ch);
                }
            }
        }
    }
    if state != State::Normal {
        return Err(MissingClosingQuote);
    }
    if let Some(w) = current.take() {
        words.push(w);
    }
    Ok(words)
}

fn needs_quoting(word: &str) -> bool {
    if word.is_empty() {
        return true;
    }
    !word.chars().all(|c| {
        c.is_alphanumeric()
            || matches!(c, '-' | '_' | '=' | '/' | ',' | '.' | ':' | '+' | '@')
    })
}

pub fn join(words: &[String]) -> String {
    let mut parts = Vec::new();
    for word in words {
        if needs_quoting(word) {
            let escaped = word.replace('\'', "'\\''");
            parts.push(format!("'{escaped}'"));
        } else {
            parts.push(word.clone());
        }
    }
    parts.join(" ")
}
