use std::fs::File;
use std::io;
use std::os::unix::process::ExitStatusExt;
use std::process::{Command, Stdio};
use std::time::Instant;

use rand::Rng;

use crate::shell_words;

#[derive(Clone, Debug)]
pub enum OutputPolicy {
    Null,
    Pipe,
    Inherit,
    File(String),
}

#[derive(Clone, Debug)]
pub enum InputPolicy {
    Null,
    File(String),
}

#[derive(Clone, Debug)]
pub struct Timing {
    pub real: f64,
    pub user: f64,
    pub system: f64,
    pub memory: u64,
    pub exit_code: Option<i32>,
    pub signal: Option<i32>,
}

#[derive(Debug)]
pub enum RunError {
    ParseError,
    EmptyCommand,
    IoPlain(io::Error),
    Spawn(io::Error),
}

fn rusage_children() -> (f64, f64, u64) {
    unsafe {
        let mut ru: libc::rusage = std::mem::zeroed();
        let ret = libc::getrusage(libc::RUSAGE_CHILDREN, &mut ru);
        if ret != 0 {
            return (0.0, 0.0, 0);
        }
        let user = ru.ru_utime.tv_sec as f64 + ru.ru_utime.tv_usec as f64 / 1e6;
        let system = ru.ru_stime.tv_sec as f64 + ru.ru_stime.tv_usec as f64 / 1e6;
        #[cfg(target_os = "linux")]
        let memory = (ru.ru_maxrss as u64).saturating_mul(1024);
        #[cfg(not(target_os = "linux"))]
        let memory = ru.ru_maxrss as u64;
        (user, system, memory)
    }
}

#[derive(Clone)]
pub struct Executor {
    shell: Option<Vec<String>>,
    shell_display: String,
    input: InputPolicy,
    shell_time: Option<(f64, f64, f64)>, // real, user, system
}

impl Executor {
    pub fn new(shell: Option<Vec<String>>, input: InputPolicy) -> Self {
        let shell_display = match &shell {
            Some(tokens) => shell_words::join(tokens),
            None => String::new(),
        };
        Self { shell, shell_display, input, shell_time: None }
    }

    pub fn has_shell(&self) -> bool { self.shell.is_some() }
    pub fn shell_display(&self) -> &str { &self.shell_display }
    pub fn set_shell_time(&mut self, t: (f64, f64, f64)) { self.shell_time = Some(t); }

    fn run_internal(
        &self,
        command_str: &str,
        iteration: Option<&str>,
        output: &OutputPolicy,
        input_override_null: bool,
    ) -> Result<Timing, RunError> {
        let mut cmd: Command;
        match &self.shell {
            Some(tokens) => {
                cmd = Command::new(&tokens[0]);
                if tokens.len() > 1 {
                    cmd.args(&tokens[1..]);
                }
                cmd.arg("-c");
                cmd.arg(command_str);
            }
            None => {
                let parts = shell_words::split(command_str).map_err(|_| RunError::ParseError)?;
                if parts.is_empty() {
                    return Err(RunError::EmptyCommand);
                }
                cmd = Command::new(&parts[0]);
                if parts.len() > 1 {
                    cmd.args(&parts[1..]);
                }
            }
        }

        if input_override_null {
            cmd.stdin(Stdio::null());
        } else {
            match &self.input {
                InputPolicy::Null => {
                    cmd.stdin(Stdio::null());
                }
                InputPolicy::File(path) => {
                    let file = File::open(path).map_err(RunError::IoPlain)?;
                    cmd.stdin(Stdio::from(file));
                }
            }
        }

        let is_pipe = matches!(output, OutputPolicy::Pipe);
        match output {
            OutputPolicy::Null => {
                cmd.stdout(Stdio::null());
                cmd.stderr(Stdio::null());
            }
            OutputPolicy::Pipe => {
                cmd.stdout(Stdio::piped());
                cmd.stderr(Stdio::null());
            }
            OutputPolicy::Inherit => {
                cmd.stdout(Stdio::inherit());
                cmd.stderr(Stdio::inherit());
            }
            OutputPolicy::File(path) => {
                let file = File::create(path).map_err(RunError::IoPlain)?;
                cmd.stdout(Stdio::from(file));
                cmd.stderr(Stdio::null());
            }
        }

        let offset_len: usize = rand::thread_rng().gen_range(0..4096);
        cmd.env(
            "HYPERFINE_RANDOMIZED_ENVIRONMENT_OFFSET",
            "X".repeat(offset_len),
        );
        if let Some(iteration) = iteration {
            cmd.env("HYPERFINE_ITERATION", iteration);
        }

        let (user_before, system_before, _) = rusage_children();
        let start = Instant::now();
        let mut child = cmd.spawn().map_err(RunError::Spawn)?;
        let status = if is_pipe {
            match child.wait_with_output() {
                Ok(out) => out.status,
                Err(e) => return Err(RunError::Spawn(e)),
            }
        } else {
            match child.wait() {
                Ok(s) => s,
                Err(e) => return Err(RunError::Spawn(e)),
            }
        };
        let real_raw = start.elapsed().as_secs_f64();
        let (user_after, system_after, memory) = rusage_children();

        let user_raw = user_after - user_before;
        let system_raw = system_after - system_before;

        let (real, user, system) = if let Some((s_real, s_user, s_system)) = self.shell_time {
            (
                (real_raw - s_real).max(0.0),
                (user_raw - s_user).max(0.0),
                (system_raw - s_system).max(0.0),
            )
        } else {
            (real_raw, user_raw, system_raw)
        };

        Ok(Timing {
            real,
            user,
            system,
            memory,
            exit_code: status.code().or_else(|| status.signal().map(|s| 128 + s)),
            signal: status.signal(),
        })
    }

    pub fn run_timed(
        &self,
        command_str: &str,
        iteration: &str,
        output: &OutputPolicy,
    ) -> Result<Timing, RunError> {
        self.run_internal(command_str, Some(iteration), output, false)
    }

    pub fn run_intermediate(
        &self,
        command_str: &str,
        output: &OutputPolicy,
    ) -> Result<Timing, RunError> {
        self.run_internal(command_str, None, output, false)
    }

    pub fn run_calibration_once(&self) -> Result<Timing, RunError> {
        self.run_internal("", None, &OutputPolicy::Null, true)
    }
}
