use std::io::{self, IsTerminal, Write};
use std::time::{Duration, Instant};

const SPINNER: &[&str] = &["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

fn terminal_width_stderr() -> usize {
    unsafe {
        #[repr(C)]
        #[derive(Default)]
        struct WinSize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16 }
        let mut winsz = WinSize::default();
        let ret = libc::ioctl(2, libc::TIOCGWINSZ, &mut winsz as *mut WinSize);
        if ret == 0 && winsz.ws_col > 0 {
            return winsz.ws_col as usize;
        }
    }
    if let Ok(cols) = std::env::var("COLUMNS") {
        if let Ok(n) = cols.parse::<usize>() {
            if n > 0 {
                return n;
            }
        }
    }
    80
}

struct Progress {
    total: Option<u64>,
    pos: u64,
    msg: String,
    msg_visible_len: usize,
    start: Instant,
    line_active: bool,
    last_draw: Option<Instant>,
}

pub struct Out {
    pub color: bool,
    progress_live: bool,
    pub disabled: bool,
    progress: Option<Progress>,
    spinner_idx: usize,
}

impl Out {
    pub fn new(color: bool, progress: bool, disabled: bool) -> Self {
        let progress_live = progress && io::stderr().is_terminal();
        Self { color, progress_live, disabled, progress: None, spinner_idx: 0 }
    }

    pub fn println(&mut self, s: &str) {
        if self.disabled {
            return;
        }
        self.finish_progress();
        println!("{s}");
    }

    pub fn blank_line(&mut self) {
        if self.disabled {
            return;
        }
        self.finish_progress();
        println!(" ");
    }

    pub fn eprintln(&self, s: &str) {
        eprintln!("{s}");
    }

    // Color helpers.  When color is disabled these return the input unchanged.
    pub fn bold(&self, s: &str) -> String {
        if self.color { format!("\x1b[1m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn bold_green(&self, s: &str) -> String {
        if self.color { format!("\x1b[1;32m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn green(&self, s: &str) -> String {
        if self.color { format!("\x1b[32m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn blue(&self, s: &str) -> String {
        if self.color { format!("\x1b[34m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn cyan(&self, s: &str) -> String {
        if self.color { format!("\x1b[36m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn magenta(&self, s: &str) -> String {
        if self.color { format!("\x1b[35m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn yellow(&self, s: &str) -> String {
        if self.color { format!("\x1b[33m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn dim(&self, s: &str) -> String {
        if self.color { format!("\x1b[2m{s}\x1b[0m") } else { s.to_string() }
    }
    pub fn bold_red(&self, s: &str) -> String {
        if self.color { format!("\x1b[1;31m{s}\x1b[0m") } else { s.to_string() }
    }

    pub fn start_progress(&mut self, total: Option<u64>, msg: String, msg_visible_len: usize) {
        if !self.progress_live || self.disabled {
            return;
        }
        self.finish_progress();
        self.progress = Some(Progress {
            total,
            pos: 0,
            msg,
            msg_visible_len,
            start: Instant::now(),
            line_active: false,
            last_draw: None,
        });
        self.draw(true);
    }

    pub fn set_progress_total(&mut self, total: Option<u64>) {
        if let Some(p) = &mut self.progress {
            p.total = total;
        }
    }

    pub fn set_progress_position(&mut self, pos: u64) {
        if let Some(p) = &mut self.progress {
            p.pos = pos;
        }
    }

    pub fn set_progress_message(&mut self, msg: String, msg_visible_len: usize) {
        if let Some(p) = &mut self.progress {
            p.msg = msg;
            p.msg_visible_len = msg_visible_len;
        }
        self.draw(false);
    }

    pub fn inc_progress(&mut self) {
        let reached_total = if let Some(p) = &mut self.progress {
            p.pos = p.pos.saturating_add(1);
            p.total.map(|t| p.pos >= t).unwrap_or(false)
        } else {
            false
        };
        self.draw(reached_total);
    }

    fn draw(&mut self, force: bool) {
        if !self.progress_live {
            return;
        }
        let now = Instant::now();
        let (line, prefix_clear) = {
            let p = match &mut self.progress {
                Some(p) => p,
                None => return,
            };
            if !force {
                if let Some(last) = p.last_draw {
                    if now.duration_since(last) < Duration::from_millis(50) {
                        return;
                    }
                }
            }
            let spinner = SPINNER[self.spinner_idx % SPINNER.len()];
            self.spinner_idx += 1;
            let width = terminal_width_stderr();
            let eta = eta_string(p.start.elapsed(), p.pos, p.total);
            // Template: ` {spinner} {msg:<31}{bar} ETA {eta} `
            let non_bar = 3 + 31 + 1 + 3 + 1 + eta.chars().count() + 1;
            let bar_width = width.saturating_sub(non_bar);
            let filled = match p.total {
                Some(total) if total > 0 => {
                    ((p.pos as f64 / total as f64) * bar_width as f64).floor() as usize
                }
                _ => 0,
            };
            let filled = filled.min(bar_width);
            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(bar_width - filled));
            let pad = 31usize.saturating_sub(p.msg_visible_len);
            let msg_padded = format!("{}{}", p.msg, " ".repeat(pad));
            let line = format!(" {spinner} {msg_padded}{bar} ETA {eta} ");
            let prefix_clear = p.line_active;
            p.line_active = true;
            p.last_draw = Some(now);
            (line, prefix_clear)
        };
        let mut stderr = io::stderr().lock();
        if prefix_clear {
            let _ = write!(stderr, "\r\x1b[2K");
        }
        let _ = write!(stderr, "{line}");
        let _ = stderr.flush();
    }

    pub fn finish_progress(&mut self) {
        if let Some(p) = self.progress.take() {
            if self.progress_live && p.line_active {
                let mut stderr = io::stderr().lock();
                let _ = write!(stderr, "\r\x1b[2K");
                let _ = stderr.flush();
            }
        }
    }
}

impl Drop for Out {
    fn drop(&mut self) {
        self.finish_progress();
    }
}

fn eta_string(elapsed: Duration, pos: u64, total: Option<u64>) -> String {
    let remaining = match total {
        Some(total) if pos > 0 && total > pos => {
            elapsed.as_secs_f64() * ((total - pos) as f64 / pos as f64)
        }
        _ => 0.0,
    };
    let secs = remaining as u64;
    let hours = secs / 3600;
    let minutes = (secs % 3600) / 60;
    let seconds = secs % 60;
    format!("{hours:02}:{minutes:02}:{seconds:02}")
}
RS
"}

