            let filled = match p.total {
                Some(total) if total > 0 => {
                    ((p.pos as f64 / total as f64) * bar_width as f64).floor() as usize
                }
                _ => 0,
            };
            let filled = filled.min(bar_width);
            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(bar_width - filled));
            let pad = 31usize.saturating_sub(p.msg_visible_len);
            let msg_padded = format!("{}{}", p.msg, " ".repeat(pad));
            let line = format!(" {spinner} {msg_padded}{bar} ETA {eta} ");
            let prefix_clear = p.line_active;
            p.line_active = true;
            p.last_draw = Some(now);
            (line, prefix_clear)
        };
        let mut stderr = io::stderr().lock();
        if prefix_clear {
            let _ = write!(stderr, "\r\x1b[2K");
        }
        let _ = write!(stderr, "{line}");
        let _ = stderr.flush();
    }

    pub fn finish_progress(&mut self) {
        if let Some(p) = self.progress.take() {
            if self.progress_live && p.line_active {
                let mut stderr = io::stderr().lock();
                let _ = write!(stderr, "\r\x1b[2K");
                let _ = stderr.flush();
            }
        }
    }
}

impl Drop for Out {
    fn drop(&mut self) {
        self.finish_progress();
    }
