use std::fs::File;
use std::io;
use std::os::unix::process::ExitStatusExt;
use std::process::{Command, Stdio};
use std::time::Instant;

use rand::Rng;

use crate::shell_words;

#[derive(Clone, Debug)]
pub enum OutputPolicy {
    Null,
    Pipe,
    Inherit,
    File(String),
}

#[derive(Clone, Debug)]
pub enum InputPolicy {
    Null,
    File(String),
}

#[derive(Clone, Debug)]
pub struct Timing {
    pub real: f64,
    pub user: f64,
    pub system: f64,
    pub memory: u64,
    pub exit_code: Option<i32>,
    pub signal: Option<i32>,
}

#[derive(Debug)]
pub enum RunError {
    ParseError,
    EmptyCommand,
    IoPlain(io::Error),
    Spawn(io::Error),
}

fn rusage_children() -> (f64, f64, u64) {
    unsafe {
        let mut ru: libc::rusage = std::mem::zeroed();
        let ret = libc::getrusage(libc::RUSAGE_CHILDREN, &mut ru);
        if ret != 0 {
            return (0.0, 0.0, 0);
        }
        let user = ru.ru_utime.tv_sec as f64 + ru.ru_utime.tv_usec as f64 / 1e6;
        let system = ru.ru_stime.tv_sec as f64 + ru.ru_stime.tv_usec as f64 / 1e6;
        #[cfg(target_os = "linux")]
        let memory = (ru.ru_maxrss as u64).saturating_mul(1024);
        #[cfg(not(target_os = "linux"))]
        let memory = ru.ru_maxrss as u64;
        (user, system, memory)
    }
}

#[derive(Clone)]
pub struct Executor {
    shell: Option<Vec<String>>,
    shell_display: String,
    input: InputPolicy,
    shell_time: Option<(f64, f64, f64)>, // real, user, system
}

impl Executor {
    pub fn new(shell: Option<Vec<String>>, input: InputPolicy) -> Self {
        let shell_display = match &shell {
            Some(tokens) => shell_words::join(tokens),
            None => String::new(),
        };
        Self { shell, shell_display, input, shell_time: None }
    }

    pub fn has_shell(&self) -> bool { self.shell.is_some() }
    pub fn shell_display(&self) -> &str { &self.shell_display }
    pub fn set_shell_time(&mut self, t: (f64, f64, f64)) { self.shell_time = Some(t); }

    fn run_internal(
        &self,
        command_str: &str,
        iteration: Option<&str>,
        output: &OutputPolicy,
        input_override_null: bool,
    ) -> Result<Timing, RunError> {
        let mut cmd: Command;
        match &self.shell {
            Some(tokens) => {
                cmd = Command::new(&tokens[0]);
                if tokens.len() > 1 {
                    cmd.args(&tokens[1..]);
                }
                cmd.arg("-c");
                cmd.arg(command_str);
            }
            None => {
                let parts = shell_words::split(command_str).map_err(|_| RunError::ParseError)?;
                if parts.is_empty() {
                    return Err(RunError::EmptyCommand);
                }
                cmd = Command::new(&parts[0]);
                if parts.len() > 1 {
                    cmd.args(&parts[1..]);
                }
            }
        }

