use std::fs::File;
use std::io::Write;

use serde::Serialize;

use crate::format::{format_duration_value, unit_from_value, Unit};
use crate::types::{fastest_index, relative_speed, BenchmarkResult};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum SortMethod {
    Auto,
    Command,
    MeanTime,
}

#[derive(Clone, Copy)]
enum ExportKind {
    Asciidoc,
    Json,
    Csv,
    Markdown,
    Orgmode,
}

enum ExportDest {
    Stdout,
    File(String),
}

struct Exporter {
    kind: ExportKind,
    dest: ExportDest,
}

pub struct ExportManager {
    exporters: Vec<Exporter>,
}

#[derive(Serialize)]
struct JsonResults<'a> {
    results: &'a [BenchmarkResult],
}

impl ExportManager {
    pub fn new(
        asciidoc: Option<&str>,
        json: Option<&str>,
        csv: Option<&str>,
        markdown: Option<&str>,
        orgmode: Option<&str>,
    ) -> Result<Self, String> {
        let mut exporters = Vec::new();
        // Creation (and later writing) happens in this fixed order.
        for (kind, path) in [
            (ExportKind::Asciidoc, asciidoc),
            (ExportKind::Json, json),
            (ExportKind::Csv, csv),
            (ExportKind::Markdown, markdown),
            (ExportKind::Orgmode, orgmode),
        ] {
            if let Some(path) = path {
                if path == "-" {
                    exporters.push(Exporter { kind, dest: ExportDest::Stdout });
                } else {
                    File::create(path)
                        .map_err(|e| format!("Could not create export file '{path}': {e}"))?;
                    exporters.push(Exporter {
                        kind,
                        dest: ExportDest::File(path.to_string()),
                    });
                }
            }
        }
        Ok(Self { exporters })
    }

    pub fn write_results(
        &self,
        results: &[BenchmarkResult],
        sort: SortMethod,
        time_unit: Option<Unit>,
        include_stdout: bool,
    ) -> Result<(), String> {
        if results.is_empty() {
            return Ok(());
        }
        for exporter in &self.exporters {
            let serialized = serialize(exporter.kind, results, sort, time_unit)?;
            match &exporter.dest {
                ExportDest::Stdout => {
                    if include_stdout {
                        println!("\n{serialized}");
                    }
                }
                ExportDest::File(path) => {
                    let write_result = (|| -> std::io::Result<()> {
                        let mut file = File::create(path)?;
                        file.write_all(serialized.as_bytes())?;
                        file.flush()
                    })();
                    if let Err(e) = write_result {
                        return Err(format!("Failed to export results to '{path}': {e}"));
                    }
                }
            }
        }
        Ok(())
    }
}

fn serialize(
    kind: ExportKind,
    results: &[BenchmarkResult],
    sort: SortMethod,
    time_unit: Option<Unit>,
) -> Result<String, String> {
    match kind {
        ExportKind::Json => {
            let text = serde_json::to_string_pretty(&JsonResults { results })
                .map_err(|e| e.to_string())?;
            Ok(format!("{text}\n"))
        }
        ExportKind::Csv => serialize_csv(results),
        ExportKind::Markdown => Ok(serialize_markdown(results, sort, time_unit)),
        ExportKind::Asciidoc => Ok(serialize_asciidoc(results, sort, time_unit)),
        ExportKind::Orgmode => Ok(serialize_orgmode(results, sort, time_unit)),
    }
}

fn csv_escape(field: &str) -> String {
    if field.contains(',') || field.contains('"') || field.contains('\n') || field.contains('\r') {
        format!("\"{}\"", field.replace('"', "\"\""))
    } else {
        field.to_string()
    }
}

fn f64_display(v: f64) -> String {
    format!("{v}")
}

fn serialize_csv(results: &[BenchmarkResult]) -> Result<String, String> {
    let first = &results[0];
    let mut header: Vec<String> = [
        "command", "mean", "stddev", "median", "user", "system", "min", "max",
    ]
    .iter()
    .map(|s| s.to_string())
    .collect();
    for key in first.parameters.keys() {
        header.push(format!("parameter_{key}"));
    }
    let header_len = header.len();
    let mut out = String::new();
    out.push_str(
        &header
            .iter()
            .map(|f| csv_escape(f))
            .collect::<Vec<_>>()
            .join(","),
    );
    out.push('\n');
    for result in results {
        let mut record: Vec<String> = vec![
            result.command.clone(),
            f64_display(result.mean),
            f64_display(result.stddev.unwrap_or(0.0)),
            f64_display(result.median),
            f64_display(result.user),
            f64_display(result.system),
            f64_display(result.min),
            f64_display(result.max),
        ];
        for value in result.parameters.values() {
            record.push(value.clone());
        }
        if record.len() != header_len {
            return Err(format!(
                "CSV error: found record with {} fields, but the previous record has {} fields",
                record.len(),
                header_len
            ));
        }
        out.push_str(
            &record
                .iter()
                .map(|f| csv_escape(f))
                .collect::<Vec<_>>()
                .join(","),
        );
        out.push('\n');
    }
    Ok(out)
}

struct MarkupRow {
    name: String,
    mean: String,
    min: String,
    max: String,
    relative: String,
}

fn markup_rows(results: &[BenchmarkResult], sort: SortMethod, time_unit: Option<Unit>) -> (Vec<MarkupRow>, Unit) {
    let unit = time_unit.unwrap_or_else(|| unit_from_value(results[0].mean));
    let fastest_idx = fastest_index(results);
    let fastest = &results[fastest_idx];
    let mut indices: Vec<usize> = (0..results.len()).collect();
    if sort == SortMethod::MeanTime {
        indices.sort_by(|&a, &b| {
            results[a]
                .mean
                .partial_cmp(&results[b].mean)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
    }
    let mut rows = Vec::new();
    for idx in indices {
        let result = &results[idx];
        let mut mean = format_duration_value(result.mean, unit);
        if let Some(sd) = result.stddev {
            mean = format!("{mean} ± {}", format_duration_value(sd, unit));
        }
        let relative = if idx == fastest_idx {
            "1.00".to_string()
        } else if fastest.mean == 0.0 {
            "inf".to_string()
        } else {
            let (ratio, uncertainty) = relative_speed(fastest, result);
            match uncertainty {
                Some(u) => format!("{ratio:.2} ± {u:.2}"),
                None => format!("{ratio:.2}"),
            }
        };
        rows.push(MarkupRow {
            name: result.display_name.replace('|', "\\|"),
            mean,
            min: format_duration_value(result.min, unit),
            max: format_duration_value(result.max, unit),
            relative,
        });
    }
    (rows, unit)
}

fn serialize_markdown(results: &[BenchmarkResult], sort: SortMethod, time_unit: Option<Unit>) -> String {
    let (rows, unit) = markup_rows(results, sort, time_unit);
    let u = unit.short();
    let mut out = String::new();
    out.push_str(&format!(
        "| Command | Mean [{u}] | Min [{u}] | Max [{u}] | Relative |\n"
    ));
    out.push_str("|:---|---:|---:|---:|---:|\n");
    for row in &rows {
        out.push_str(&format!(
            "| `{}` | {} | {} | {} | {} |\n",
            row.name, row.mean, row.min, row.max, row.relative
        ));
    }
    out
}

fn serialize_asciidoc(results: &[BenchmarkResult], sort: SortMethod, time_unit: Option<Unit>) -> String {
    let (rows, unit) = markup_rows(results, sort, time_unit);
    let u = unit.short();
    let mut out = String::new();
    out.push_str("[cols=\"<,>,>,>,>\"]\n|===\n");
    out.push_str(&format!(
        "| Command \n| Mean [{u}] \n| Min [{u}] \n| Max [{u}] \n| Relative \n\n"
    ));
    for (i, row) in rows.iter().enumerate() {
        if i > 0 {
            out.push('\n');
        }
        out.push_str(&format!(
            "| `{}` \n| {} \n| {} \n| {} \n| {} \n",
            row.name, row.mean, row.min, row.max, row.relative
        ));
    }
    out.push_str("|===\n");
    out
}

fn serialize_orgmode(results: &[BenchmarkResult], sort: SortMethod, time_unit: Option<Unit>) -> String {
    let (rows, unit) = markup_rows(results, sort, time_unit);
    let u = unit.short();
    let mut out = String::new();
    out.push_str(&format!(
        "| Command  |  Mean [{u}] |  Min [{u}] |  Max [{u}] |  Relative |\n"
    ));
    out.push_str("|--+--+--+--+--|\n");
    for row in &rows {
        out.push_str(&format!(
            "| ={}=  |  {} |  {} |  {} |  {} |\n",
            row.name, row.mean, row.min, row.max, row.relative
        ));
    }
    out
}
RS
"}

