static ERROR_COLOR: AtomicBool = AtomicBool::new(false);

fn colored_default() -> bool {
    if std::env::var_os("CLICOLOR_FORCE").is_some() {
        return true;
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
