}

fn auto_color_enabled() -> bool {
    // Based on TERM / NO_COLOR (NO_COLOR only counts when non-empty here).
    match std::env::var_os("TERM") {
        None => false,
        Some(term) => {
            if term == "dumb" {
                return false;
            }
            match std::env::var_os("NO_COLOR") {
                Some(v) if !v.is_empty() => false,
                _ => true,
            }
        }
    }
}

fn error_exit(message: &str) -> ! {
    if ERROR_COLOR.load(AtomicOrdering::Relaxed) {
        eprintln!("\x1b[31mError:\x1b[0m {message}");
    } else {
        eprintln!("Error: {message}");
    }
    std::process::exit(1);
}

fn parse_u64_arg(value: Option<&String>, name: &str) -> Result<Option<u64>, String> {
    match value {
        None => Ok(None),
        Some(s) => s
            .parse::<u64>()
            .map(Some)
            .map_err(|e| format!("Could not read numeric integer argument to '{name}': {e}")),
    }
}

#[derive(Clone, Copy)]
struct RunRange {
    min: u64,
    max: Option<u64>,
}

#[derive(Clone)]
enum IgnoreFailure {
    Disabled,
    All,
    Specific(HashSet<i32>),
}

impl IgnoreFailure {
    fn allows(&self, code: i32) -> bool {
        if code == 0 {
            return true;
        }
        match self {
            IgnoreFailure::Disabled => false,
            IgnoreFailure::All => true,
            IgnoreFailure::Specific(set) => set.contains(&code),
        }
    }
}

struct BenchCommand {
    display_name: String,
    export_name: String,
    expression: String,
    params: Vec<(String, String)>, // in parameter-definition order
    params_btree: BTreeMap<String, String>,
    prepare: Option<String>,
    conclude: Option<String>,
    output: OutputPolicy,
}

struct AppOptions {
    warmup: u64,
    run_range: RunRange,
    shell: Option<Vec<String>>,
    ignore_failure: IgnoreFailure,
    input: InputPolicy,
    sort: SortMethod,
    time_unit: Option<Unit>,
    setup: Option<String>,
    cleanup: Option<String>,
    out: Out,
    has_reference: bool,
}

fn replace_parameters(input: &str, params: &[(String, String)]) -> String {
    if params.is_empty() || input.is_empty() {
        return input.to_string();
    }
    let placeholders: Vec<String> = params.iter().map(|(k, _)| format!("{{{k}}}")).collect();
    let mut output = String::with_capacity(input.len());
    let mut rest = input;
    'outer: while !rest.is_empty() {
        for (i, placeholder) in placeholders.iter().enumerate() {
            if let Some(stripped) = rest.strip_prefix(placeholder.as_str()) {
                output.push_str(&params[i].1);
                rest = stripped;
                continue 'outer;
            }
        }
        let mut chars = rest.chars();
        if let Some(ch) = chars.next() {
            output.push(ch);
            rest = chars.as_str();
        } else {
            break;
        }
    }
    output
}

fn get_many_strings(matches: &ArgMatches, id: &str) -> Vec<String> {
    match matches.get_many::<String>(id) {
        Some(values) => values.cloned().collect(),
        None => Vec::new(),
    }
}

fn parse_output_policy(s: &str) -> Result<OutputPolicy, String> {
    match s {
        "null" => Ok(OutputPolicy::Null),
        "pipe" => Ok(OutputPolicy::Pipe),
        "inherit" => Ok(OutputPolicy::Inherit),
        _ if s.contains('/') => Ok(OutputPolicy::File(s.to_string())),
        _ => Err(format!(
            "Unknown output policy '{s}'. Use './{s}' to output to a file named '{s}'."
        )),
    }
}

fn build_parameter_combinations(
    matches: &ArgMatches,
) -> Result<(bool, Vec<Vec<(String, String)>>), String> {
    // Parameter scan
    if let Some(values) = matches.get_many::<String>("parameter-scan") {
        let vals: Vec<&String> = values.collect();
        let var = vals[0].clone();
        let scanned = decimal::build_scan_values(
            vals[1],
            vals[2],
            matches.get_one::<String>("parameter-step-size").map(|s| s.as_str()),
        )?;
        let combos = scanned
            .into_iter()
            .map(|v| vec![(var.clone(), v)])
            .collect();
        return Ok((true, combos));
    }

    // Parameter lists
    let list_values = get_many_strings(matches, "parameter-list");
    if !list_values.is_empty() {
        let mut defs: Vec<(String, Vec<String>)> = Vec::new();
        let mut i = 0;
        while i + 1 < list_values.len() {
            let name = list_values[i].clone();
            let values = list_values[i + 1]
                .split(',')
                .map(|v| v.to_string())
                .collect::<Vec<_>>();
            defs.push((name, values));
            i += 2;
        }
        // Duplicate detection (sorted, de-duplicated)
        let mut seen = HashSet::new();
        let mut duplicates = BTreeSet::new();
        for (name, _) in &defs {
            if !seen.insert(name.clone()) {
                duplicates.insert(name.clone());
            }
        }
        if !duplicates.is_empty() {
            let list = duplicates.into_iter().collect::<Vec<_>>().join(", ");
            return Err(format!("Duplicate parameter names: {list}"));
        }
        // Cartesian product with the first parameter varying fastest.
        let total: usize = defs.iter().map(|(_, vs)| vs.len()).product();
        let mut combos = Vec::with_capacity(total);
        for idx in 0..total {
            let mut remainder = idx;
            let mut combo = Vec::with_capacity(defs.len());
            for (name, values) in &defs {
                let choice = remainder % values.len();
                remainder /= values.len();
                combo.push((name.clone(), values[choice].clone()));
            }
            combos.push(combo);
        }
        return Ok((true, combos));
    }

    Ok((false, vec![Vec::new()]))
}

fn build_benchmarks(
    matches: &ArgMatches,
    has_params: bool,
    combinations: &[Vec<(String, String)>],
) -> Result<Vec<BenchCommand>, String> {
    let commands = get_many_strings(matches, "command");
    let names = get_many_strings(matches, "command-name");

    let mut benchmarks: Vec<BenchCommand> = Vec::new();

    if !has_params {
        if names.len() > commands.len() {
            return Err(format!(
                "Too many --command-name options: Expected {} at most",
                commands.len()
            ));
        }
        for (i, cmd) in commands.iter().enumerate() {
            let export_name = names.get(i).cloned().unwrap_or_else(|| cmd.clone());
            benchmarks.push(BenchCommand {
                display_name: export_name.clone(),
                export_name,
                expression: cmd.clone(),
                params: Vec::new(),
                params_btree: BTreeMap::new(),
                prepare: None,
                conclude: None,
                output: OutputPolicy::Null,
            });
        }
    } else {
        let total = combinations.len() * commands.len();
        if !names.is_empty() && names.len() != 1 && names.len() != total {
            return Err(format!(
                "'--command-name' has been specified {} times. It has to appear exactly once, or exactly {} times (number of benchmarks)",
                names.len(),
                total
            ));
        }
        let mut expanded_idx = 0usize;
        for combo in combinations {
            for cmd in &commands {
                let name_pattern: &str = if names.len() == 1 {
                    &names[0]
                } else if names.len() == total {
                    &names[expanded_idx]
                } else {
                    cmd.as_str()
                };
                let expression = replace_parameters(cmd, combo);
                let export_name = replace_parameters(name_pattern, combo);
                // Suffix: parameters whose placeholder does not occur in
                // the (original) command expression.
                let suffix_params: Vec<&(String, String)> = combo
                    .iter()
                    .filter(|(name, _)| !cmd.contains(&format!("{{{name}}}")))
                    .collect();
                let display_name = if suffix_params.is_empty() {
                    export_name.clone()
                } else {
                    let inner = suffix_params
                        .iter()
                        .map(|(k, v)| format!("{k} = {v}"))
                        .collect::<Vec<_>>()
                        .join(", ");
                    format!("{export_name} ({inner})")
                };
                let params_btree: BTreeMap<String, String> = combo.iter().cloned().collect();
                benchmarks.push(BenchCommand {
                    display_name,
                    export_name,
                    expression,
                    params: combo.clone(),
                    params_btree,
                    prepare: None,
                    conclude: None,
                    output: OutputPolicy::Null,
                });
                expanded_idx += 1;
            }
        }
    }

    // Reference command is prepended (without parameter replacement).
    if let Some(reference) = matches.get_one::<String>("reference") {
        let export_name = matches
            .get_one::<String>("reference-name")
            .cloned()
            .unwrap_or_else(|| reference.clone());
        benchmarks.insert(
            0,
            BenchCommand {
                display_name: export_name.clone(),
                export_name,
                expression: reference.clone(),
                params: Vec::new(),
                params_btree: BTreeMap::new(),
                prepare: None,
                conclude: None,
                output: OutputPolicy::Null,
            },
        );
    }

    Ok(benchmarks)
}

fn resolve_per_benchmark<T: Clone>(
    items: &[T],
    total: usize,
    opt_name: &str,
) -> Result<Vec<Option<T>>, String> {
    if items.is_empty() {
        return Ok(vec![None; total]);
    }
    if items.len() == 1 {
        return Ok(vec![Some(items[0].clone()); total]);
    }
    if items.len() == total {
        return Ok(items.iter().map(|item| Some(item.clone())).collect());
    }
    Err(format!(
        "The '{opt_name}' option has to be provided just once or N times, where N={total} is the number of benchmark commands (including a potential reference)."
    ))
}

fn median_of(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    let mut sorted = values.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let n = sorted.len();
    if n % 2 == 1 {
        sorted[n / 2]
    } else {
        (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
    }
}

fn mean_of(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    values.iter().sum::<f64>() / values.len() as f64
}

fn sample_stddev(values: &[f64], mean: f64) -> Option<f64> {
    if values.len() < 2 {
        return None;
    }
    let variance = values
        .iter()
        .map(|v| (v - mean).powi(2))
        .sum::<f64>()
        / (values.len() - 1) as f64;
    Some(variance.sqrt())
}

fn first_run_slower_message(time_first: f64, warmup_used: bool, prepare_used: bool) -> String {
    let formatted = format_duration(time_first, None);
    let base = format!(
        "The first benchmarking run for this command was significantly slower than the rest ({formatted}). This could be caused by (filesystem) caches that were not filled until after the first run."
    );
    let suffix = match (warmup_used, prepare_used) {
        (false, false) => "You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.",
        (true, false) => "You are already using the '--warmup' option which helps to fill these caches before the actual benchmark. You can either try to increase the warmup count further or re-run this benchmark on a quiet system in case it was a random outlier. Alternatively, consider using the '--prepare' option to clear the caches before each timing run.",
        (false, true) => "You are already using the '--prepare' option which can be used to clear caches. If you did not use a cache-clearing command with '--prepare', you can either try that or consider using the '--warmup' option to fill those caches before the actual benchmark.",
        (true, true) => "You are already using both the '--warmup' option as well as the '--prepare' option. Consider re-running the benchmark on a quiet system. Maybe it was a random outlier. Alternatively, consider increasing the warmup count.",
    };
    format!("{base} {suffix}")
}

fn outlier_warning(times: &[f64], warmup_used: bool, prepare_used: bool) -> Option<String> {
    if times.len() < 2 {
        return None;
    }
    let median = median_of(times);
    let deviations: Vec<f64> = times.iter().map(|t| (t - median).abs()).collect();
    let mad = median_of(&deviations);
    let score = |t: f64| -> f64 {
        if mad == 0.0 {
            if t == median { 0.0 } else { f64::INFINITY }
        } else {
            0.6745 * (t - median).abs() / mad
        }
    };
    let scores: Vec<f64> = times.iter().map(|&t| score(t)).collect();
    if !scores.iter().any(|&s| s > 10.0) {
        return None;
    }
    if scores[0] > 10.0 && times[0] > median {
        Some(first_run_slower_message(times[0], warmup_used, prepare_used))
    } else {
        let mut msg = "Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs.".to_string();
        if !(warmup_used && prepare_used) {
            msg.push_str(" It might help to use the '--warmup' or '--prepare' options.");
        }
        Some(msg)
    }
}

enum RunKind {
    Warmup(u64),
    Benchmark(u64),
}

impl RunKind {
    fn phrase(&self) -> String {
        match self {
            RunKind::Warmup(0) => "the first warmup run".to_string(),
            RunKind::Warmup(i) => format!("warmup iteration {i}"),
            RunKind::Benchmark(0) => "the first benchmark run".to_string(),
            RunKind::Benchmark(i) => format!("benchmark iteration {i}"),
        }
    }
    fn iteration_env(&self) -> String {
        match self {
            RunKind::Warmup(i) => format!("warmup-{i}"),
            RunKind::Benchmark(i) => format!("{i}"),
        }
    }
}

fn run_timed_command(
    executor: &Executor,
    command_str: &str,
    kind: &RunKind,
    output: &OutputPolicy,
    ignore_failure: &IgnoreFailure,
) -> Result<Timing, String> {
    let iteration = kind.iteration_env();
    let timing = executor
        .run_timed(command_str, &iteration, output)
        .map_err(|e| match e {
            RunError::ParseError => {
                format!("Failed to parse command '{command_str}': missing closing quote")
            }
            RunError::EmptyCommand => "Can not execute empty command".to_string(),
            RunError::IoPlain(e) => format!("{e}"),
            RunError::Spawn(e) => format!("Failed to run command '{command_str}': {e}"),
        })?;
    let code = timing.exit_code.unwrap_or(0);
    if !ignore_failure.allows(code) {
        let phrase = kind.phrase();
        if timing.signal.is_some() {
            return Err(format!(
                "The process has been terminated by a signal in {phrase}. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong."
            ));
        } else {
            return Err(format!(
                "Command terminated with non-zero exit code {code} in {phrase}. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong."
            ));
        }
    }
    Ok(timing)
}

fn run_intermediate_command(
    executor: &Executor,
    command_str: &str,
    output: &OutputPolicy,
    error_message: &str,
) -> Result<(), String> {
    match executor.run_intermediate(command_str, output) {
        Ok(timing) if timing.exit_code == Some(0) => Ok(()),
        _ => Err(error_message.to_string()),
    }
}

const SETUP_ERROR: &str = "The setup command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.";
const PREPARE_ERROR: &str = "The preparation command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.";
const CONCLUDE_ERROR: &str = "The conclusion command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.";
const CLEANUP_ERROR: &str = "The cleanup command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.";

fn print_benchmark_result(out: &mut Out, result: &BenchmarkResult, time_unit: Option<Unit>) {
    if out.disabled {
        return;
    }
    let unit = time_unit.unwrap_or_else(|| unit_from_value(result.mean));
    let n = result.times.len();
    let user_str = format_duration_with_unit(result.user, unit);
    let system_str = format_duration_with_unit(result.system, unit);
    if n == 1 {
        let field = out.bold_green(&format!("{:>8}", format_duration_with_unit(result.mean, unit)));
        let line = format!(
            "  Time ({} \u{2261}):        {field}               [User: {}, System: {}]",
            out.bold_green("abs"),
            out.blue(&user_str),
            out.blue(&system_str)
        );
        out.println(&line);
    } else {
        let mean_field = out.bold_green(&format!(
            "{:>8}",
            format_duration_with_unit(result.mean, unit)
        ));
        let stddev_field = out.green(&format!(
            "{:>8}",
            format_duration_with_unit(result.stddev.unwrap_or(0.0), unit)
        ));
        let time_line = format!(
            "  Time ({} \u{00b1} {}):     {mean_field} \u{00b1} {stddev_field}    [User: {}, System: {}]",
            out.bold_green("mean"),
            out.green("\u{03c3}"),
            out.blue(&user_str),
            out.blue(&system_str)
        );
        out.println(&time_line);
        let min_field = out.cyan(&format!(
            "{:>8}",
            format_duration_with_unit(result.min, unit)
        ));
        let max_field = out.magenta(&format!(
            "{:>8}",
            format_duration_with_unit(result.max, unit)
        ));
        let range_line = format!(
            "  Range ({} \u{2026} {}):   {min_field} \u{2026} {max_field}    {}",
            out.cyan("min"),
            out.magenta("max"),
            out.dim(&format!("{n} runs"))
        );
        out.println(&range_line);
    }
    out.blank_line();
}

fn collect_warnings(
    result: &BenchmarkResult,
    has_shell: bool,
    warmup_used: bool,
    prepare_used: bool,
) -> Vec<String> {
    let mut warnings = Vec::new();
    if has_shell && result.min < 0.005 {
        warnings.push(
            "Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely."
                .to_string(),
        );
    }
    if result.exit_codes.iter().any(|&c| c != 0) {
        warnings.push("Ignoring non-zero exit code.".to_string());
    }
    if let Some(w) = outlier_warning(&result.times, warmup_used, prepare_used) {
        warnings.push(w);
    }
    warnings
}

fn print_warnings(out: &Out, warnings: &[String]) {
    if warnings.is_empty() {
        return;
    }
    out.eprintln(" ");
    for warning in warnings {
        out.eprintln(&format!("  {}: {warning}", out.yellow("Warning")));
    }
}

fn print_summary(
    out: &mut Out,
    results: &[BenchmarkResult],
    sort: SortMethod,
    has_reference: bool,
) {
    if out.disabled || results.len() < 2 {
        return;
    }
    if results.iter().any(|r| r.mean == 0.0) {
        out.eprintln(&format!(
            "{}: The benchmark comparison could not be computed as some benchmark times are zero. This could be caused by background interference during the initial calibration phase of hyperfine, in combination with very fast commands (faster than a few milliseconds). Try to re-run the benchmark on a quiet system. If you did not do so already, try the --shell=none/-N option. If it does not help either, you command is most likely too fast to be accurately benchmarked by hyperfine.",
            out.bold_red("Note")
        ));
        return;
    }

    if sort == SortMethod::Command {
        out.println(&out.bold("Relative speed comparison"));
        let base_idx = if has_reference { 0 } else { fastest_index(results) };
        let base = &results[base_idx];
        for (i, result) in results.iter().enumerate() {
            let (ratio, uncertainty) = if i == base_idx {
                (1.0, None)
            } else {
                relative_speed(base, result)
            };
            let line = if out.color {
                let mut s = format!("  {}", out.bold_green(&format!("{ratio:10.2}")));
                match uncertainty {
                    Some(u) => {
                        s.push_str(&format!(" \u{00b1} {}  {}", out.green(&format!("{u:5.2}")), result.display_name));
                    }
                    None => {
                        s.push_str(&format!("          {}", result.display_name));
                    }
                }
                s
            } else {
                let mut s = format!("{ratio:12.2}");
                match uncertainty {
                    Some(u) => s.push_str(&format!(" \u{00b1} {u:5.2}  {}", result.display_name)),
                    None => s.push_str(&format!("          {}", result.display_name)),
                }
                s
            };
            out.println(&line);
        }
        return;
    }

    // Summary (auto / mean-time)
    out.println(&out.bold("Summary"));
    let subject_idx = if has_reference { 0 } else { fastest_index(results) };
    let subject = &results[subject_idx];
    out.println(&format!("  {} ran", out.cyan(&subject.display_name)));
    let mut other_indices: Vec<usize> = (0..results.len()).filter(|&i| i != subject_idx).collect();
    other_indices.sort_by(|&a, &b| {
        results[a]
            .mean
            .partial_cmp(&results[b].mean)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    for idx in other_indices {
        let other = &results[idx];
        let (ratio, uncertainty) = relative_speed(subject, other);
        let direction = if subject.mean > other.mean { "slower" } else { "faster" };
        let line = if out.color {
            let mut s = out.bold_green(&format!("{ratio:8.2}"));
            if let Some(u) = uncertainty {
                s.push_str(&format!(" \u{00b1} {}", out.green(&format!("{u:.2}"))));
            }
            s.push_str(&format!(
                " times {direction} than {}",
                out.magenta(&other.display_name)
            ));
            s
        } else {
            let mut s = format!("{ratio:8.2}");
            if let Some(u) = uncertainty {
                s.push_str(&format!(" \u{00b1} {u:.2}"));
            }
            s.push_str(&format!(" times {direction} than {}", other.display_name));
            s
        };
        out.println(&line);
    }
}

fn run_benchmark(
    bench: &BenchCommand,
    index: usize,
    executor: &Executor,
    options: &AppOptions,
    out: &mut Out,
) -> Result<BenchmarkResult, String> {
    if !out.disabled {
        let header = if out.color {
            format!(
                "{}{}: {}",
                out.bold("Benchmark "),
                out.bold(&format!("{}", index + 1)),
                bench.display_name
            )
        } else {
            format!("Benchmark {}: {}", index + 1, bench.display_name)
        };
        out.println(&header);
    }

    let prepare_used = bench.prepare.is_some();
    let run_prepare = |executor: &Executor| -> Result<(), String> {
        if let Some(pattern) = &bench.prepare {
            let cmd = replace_parameters(pattern, &bench.params);
            run_intermediate_command(executor, &cmd, &bench.output, PREPARE_ERROR)?;
        }
        Ok(())
    };
    let run_conclude = |executor: &Executor| -> Result<(), String> {
        if let Some(pattern) = &bench.conclude {
            let cmd = replace_parameters(pattern, &bench.params);
            run_intermediate_command(executor, &cmd, &bench.output, CONCLUDE_ERROR)?;
        }
        Ok(())
    };

    if let Some(pattern) = &options.setup {
        let cmd = replace_parameters(pattern, &bench.params);
        run_intermediate_command(executor, &cmd, &bench.output, SETUP_ERROR)?;
    }

    if options.warmup > 0 {
        out.start_progress(
            Some(options.warmup),
            "Performing warmup runs".to_string(),
            "Performing warmup runs".chars().count(),
        );
        for w in 0..options.warmup {
            let result = (|| -> Result<(), String> {
                run_prepare(executor)?;
                run_timed_command(
                    executor,
                    &bench.expression,
                    &RunKind::Warmup(w),
                    &bench.output,
                    &options.ignore_failure,
                )?;
                run_conclude(executor)?;
                Ok(())
            })();
            if let Err(e) = result {
                out.finish_progress();
                return Err(e);
            }
            out.inc_progress();
        }
        out.finish_progress();
    }

    out.start_progress(
        None,
        "Initial time measurement".to_string(),
        "Initial time measurement".chars().count(),
    );

    let mut times_real: Vec<f64> = Vec::new();
    let mut times_user: Vec<f64> = Vec::new();
    let mut times_system: Vec<f64> = Vec::new();
    let mut memory_usage: Vec<u64> = Vec::new();
    let mut exit_codes: Vec<i32> = Vec::new();

    let mut record = |timing: Timing,
                      times_real: &mut Vec<f64>,
                      times_user: &mut Vec<f64>,
                      times_system: &mut Vec<f64>,
                      memory_usage: &mut Vec<u64>,
                      exit_codes: &mut Vec<i32>| {
        times_real.push(timing.real);
        times_user.push(timing.user);
        times_system.push(timing.system);
        memory_usage.push(timing.memory);
        exit_codes.push(timing.exit_code.unwrap_or(0));
    };

    // First timing run (used to estimate the total number of runs).
    let estimate_start = Instant::now();
    let first_result = (|| -> Result<Timing, String> {
        run_prepare(executor)?;
        let timing = run_timed_command(
            executor,
            &bench.expression,
            &RunKind::Benchmark(0),
            &bench.output,
            &options.ignore_failure,
        )?;
        run_conclude(executor)?;
        Ok(timing)
    })();
    let first_timing = match first_result {
        Ok(t) => t,
        Err(e) => {
            out.finish_progress();
            return Err(e);
        }
    };
    let first_elapsed = estimate_start.elapsed().as_secs_f64();
    record(
        first_timing,
        &mut times_real,
        &mut times_user,
        &mut times_system,
        &mut memory_usage,
        &mut exit_codes,
    );

    // Determine the total number of runs.
    let total_count: u64 = {
        let estimate = if first_elapsed > 0.0 {
            (3.0 / first_elapsed) as u64
        } else {
            u64::MAX
        };
        let mut count = estimate;
        if count < options.run_range.min {
            count = options.run_range.min;
        }
        if let Some(max) = options.run_range.max {
            if count > max {
                count = max;
            }
        }
        count
    };

    let update_estimate = |out: &mut Out, times_real: &[f64]| {
        let mean = mean_of(times_real);
        let plain = format!("Current estimate: {}", format_duration(mean, options.time_unit));
        let visible = plain.chars().count();
        let colored = if out.color {
            format!(
                "Current estimate: {}",
                out.green(&format_duration(mean, options.time_unit))
            )
        } else {
            plain
        };
        out.set_progress_message(colored, visible);
    };

    if total_count == 0 {
        // Matches the reference behaviour for a zero run count: it keeps
        // running (effectively forever).
        out.set_progress_total(None);
        out.set_progress_position(1);
        update_estimate(out, &times_real);
        let mut i: u64 = 1;
        loop {
            let result = (|| -> Result<Timing, String> {
                run_prepare(executor)?;
                let timing = run_timed_command(
                    executor,
                    &bench.expression,
                    &RunKind::Benchmark(i),
                    &bench.output,
                    &options.ignore_failure,
                )?;
                run_conclude(executor)?;
                Ok(timing)
            })();
            match result {
                Ok(timing) => {
                    record(
                        timing,
                        &mut times_real,
                        &mut times_user,
                        &mut times_system,
                        &mut memory_usage,
                        &mut exit_codes,
                    );
                    out.inc_progress();
                    update_estimate(out, &times_real);
                }
                Err(e) => {
                    out.finish_progress();
                    return Err(e);
                }
            }
            i = i.wrapping_add(1);
        }
    }

    if total_count > 1 {
        out.set_progress_total(Some(total_count));
        out.set_progress_position(1);
        update_estimate(out, &times_real);
        // Draw the first "current estimate" frame.
        out.set_progress_position(1);
    }

    for i in 1..total_count {
        let result = (|| -> Result<Timing, String> {
            run_prepare(executor)?;
            let timing = run_timed_command(
                executor,
                &bench.expression,
                &RunKind::Benchmark(i),
                &bench.output,
                &options.ignore_failure,
            )?;
            run_conclude(executor)?;
            Ok(timing)
        })();
        match result {
            Ok(timing) => {
                record(
                    timing,
                    &mut times_real,
                    &mut times_user,
                    &mut times_system,
                    &mut memory_usage,
                    &mut exit_codes,
                );
                out.inc_progress();
                if total_count > 1 {
                    update_estimate(out, &times_real);
                }
            }
            Err(e) => {
                out.finish_progress();
                return Err(e);
            }
        }
    }
    out.finish_progress();

    let mean = mean_of(&times_real);
    let result = BenchmarkResult {
        command: bench.export_name.clone(),
        mean,
        stddev: sample_stddev(&times_real, mean),
        median: median_of(&times_real),
        user: mean_of(&times_user),
        system: mean_of(&times_system),
        min: times_real.iter().copied().fold(f64::INFINITY, f64::min),
        max: times_real.iter().copied().fold(f64::NEG_INFINITY, f64::max),
        times: times_real,
        memory_usage_byte: memory_usage,
        exit_codes,
        parameters: bench.params_btree.clone(),
        display_name: bench.display_name.clone(),
    };

    print_benchmark_result(out, &result, options.time_unit);
    let warnings = collect_warnings(
        &result,
        executor.has_shell(),
        options.warmup > 0,
        prepare_used,
    );
    print_warnings(out, &warnings);

    if let Some(pattern) = &options.cleanup {
        let cmd = replace_parameters(pattern, &bench.params);
        run_intermediate_command(executor, &cmd, &bench.output, CLEANUP_ERROR)?;
    }

    Ok(result)
}

fn run(matches: &ArgMatches) -> Result<(), String> {
    // --- warmup ---
    let warmup = parse_u64_arg(matches.get_one::<String>("warmup"), "--warmup")?.unwrap_or(0);

    // --- run range ---
    let run_range = if let Some(runs) = parse_u64_arg(matches.get_one::<String>("runs"), "--runs")? {
        RunRange { min: runs, max: Some(runs) }
    } else {
        let explicit_min = parse_u64_arg(matches.get_one::<String>("min-runs"), "--min-runs")?;
        let explicit_max = parse_u64_arg(matches.get_one::<String>("max-runs"), "--max-runs")?;
        if let (Some(min), Some(max)) = (explicit_min, explicit_max) {
            if min > max {
                return Err(
                    "Conflicting requirements for the number of runs (empty range, min is larger than max)"
                        .to_string(),
                );
            }
        }
        let mut min = explicit_min.unwrap_or(10);
        if explicit_min.is_none() {
            if let Some(max) = explicit_max {
                if min > max {
                    min = max;
                }
            }
        }
        RunRange { min, max: explicit_max }
    };

    // --- output policies ---
    let show_output = matches.get_flag("show-output");
    let output_policies: Vec<OutputPolicy> = if show_output {
        vec![OutputPolicy::Inherit]
    } else {
        let raw = get_many_strings(matches, "output");
        let mut policies = Vec::new();
        for s in &raw {
            policies.push(parse_output_policy(s)?);
        }
        policies
    };

    // --- output style (determining it also fixes the error colour) ---
    let style_str = matches
        .get_one::<String>("style")
        .map(|s| s.as_str())
        .unwrap_or("auto");
    let (color, progress, disabled) = if show_output {
        (false, false, false)
    } else {
        match style_str {
            "basic" => (false, false, false),
            "full" => (true, true, false),
            "nocolor" => (false, true, false),
            "color" => (true, false, false),
            "none" => (false, false, true),
            _ => {
                // auto
                if std::io::stdout().is_terminal() {
                    (auto_color_enabled(), true, false)
                } else {
                    (false, false, false)
                }
            }
        }
    };
    ERROR_COLOR.store(color, AtomicOrdering::Relaxed);
    let mut out = Out::new(color, progress, disabled);

    let sort = match matches.get_one::<String>("sort").map(|s| s.as_str()) {
        Some("command") => SortMethod::Command,
        Some("mean-time") => SortMethod::MeanTime,
        _ => SortMethod::Auto,
    };
    let time_unit = matches
        .get_one::<String>("time-unit")
        .and_then(|s| Unit::from_str(s));

    // --- shell ---
    let shell: Option<Vec<String>> = if matches.get_flag("shell-none") {
        None
    } else if let Some(shell_str) = matches.get_one::<String>("shell") {
        if shell_str == "none" {
            None
        } else if shell_str == "default" {
            Some(vec!["sh".to_string()])
        } else {
            let tokens = shell_words::split(shell_str).map_err(|_| {
                "Failed to parse '--shell <command>' expression as command line: missing closing quote"
                    .to_string()
            })?;
            if tokens.is_empty() {
                return Err(
                    "An empty command has been specified for the '--shell <command>' option"
                        .to_string(),
                );
            }
            Some(tokens)
        }
    } else {
        Some(vec!["sh".to_string()])
    };

    // --- ignore-failure ---
    let ignore_failure = match matches.get_one::<String>("ignore-failure") {
        None => IgnoreFailure::Disabled,
        Some(mode) => {
            if mode == "all-non-zero" || mode.is_empty() {
                IgnoreFailure::All
            } else {
                let mut set = HashSet::new();
                for part in mode.split(',') {
                    let code = part.trim().parse::<i32>().map_err(|e| {
                        format!("Could not read numeric integer argument to '--ignore-failure': {e}")
                    })?;
                    set.insert(code);
                }
                IgnoreFailure::Specific(set)
            }
        }
    };

    // --- input ---
    let input = match matches.get_one::<String>("input") {
        None => InputPolicy::Null,
        Some(s) if s == "null" => InputPolicy::Null,
        Some(s) => {
            if !Path::new(s).exists() {
                return Err(format!("The file '{s}' specified as '--input' does not exist"));
            }
            InputPolicy::File(s.clone())
        }
    };

    // --- parameters ---
    let (has_params, combinations) = build_parameter_combinations(matches)?;

    // --- benchmark commands (incl. command-name validation) ---
    let mut benchmarks = build_benchmarks(matches, has_params, &combinations)?;
    let has_reference = matches.get_one::<String>("reference").is_some();

    // --- export files (created/truncated now) ---
    let export_manager = ExportManager::new(
        matches.get_one::<String>("export-asciidoc").map(|s| s.as_str()),
        matches.get_one::<String>("export-json").map(|s| s.as_str()),
        matches.get_one::<String>("export-csv").map(|s| s.as_str()),
        matches.get_one::<String>("export-markdown").map(|s| s.as_str()),
        matches.get_one::<String>("export-orgmode").map(|s| s.as_str()),
    )?;

    // --- per-benchmark prepare / conclude / output resolution ---
    let total = benchmarks.len();
    let prepares = resolve_per_benchmark(
        &get_many_strings(matches, "prepare"),
        total,
        "--prepare",
    )?;
    let concludes = resolve_per_benchmark(
        &get_many_strings(matches, "conclude"),
        total,
        "--conclude",
    )?;
    let outputs = resolve_per_benchmark(&output_policies, total, "--output")?;
    for (i, bench) in benchmarks.iter_mut().enumerate() {
        bench.prepare = prepares[i].clone();
        bench.conclude = concludes[i].clone();
        bench.output = outputs[i].clone().unwrap_or(OutputPolicy::Null);
    }

    let options = AppOptions {
        warmup,
        run_range,
        shell: shell.clone(),
        ignore_failure,
        input: input.clone(),
        sort,
        time_unit,
        setup: matches.get_one::<String>("setup").cloned(),
        cleanup: matches.get_one::<String>("cleanup").cloned(),
        out: Out::new(color, progress, disabled),
        has_reference,
    };
    // `out` created above is superseded by the one in options; silence the
    // unused warning by dropping it explicitly.
    drop(out);
    let mut out = options.out;
    let options_ref = &AppOptions {
        warmup: options.warmup,
        run_range: options.run_range,
        shell: options.shell.clone(),
        ignore_failure: match &options.ignore_failure {
            IgnoreFailure::Disabled => IgnoreFailure::Disabled,
            IgnoreFailure::All => IgnoreFailure::All,
            IgnoreFailure::Specific(s) => IgnoreFailure::Specific(s.clone()),
        },
        input: options.input.clone(),
        sort: options.sort,
        time_unit: options.time_unit,
        setup: options.setup.clone(),
        cleanup: options.cleanup.clone(),
        out: Out::new(color, progress, disabled),
        has_reference: options.has_reference,
    };

    let mut executor = Executor::new(shell, input);

    // --- shell spawning time calibration ---
    if executor.has_shell() {
        out.start_progress(
            Some(50),
            "Measuring shell spawning time".to_string(),
            "Measuring shell spawning time".chars().count(),
        );
        let mut calibration_error: Option<String> = None;
        let mut sum_real = 0.0f64;
        let mut sum_user = 0.0f64;
        let mut sum_system = 0.0f64;
        for _ in 0..50 {
            match executor.run_calibration_once() {
                Ok(timing) if timing.exit_code == Some(0) => {
                    sum_real += timing.real;
                    sum_user += timing.user;
                    sum_system += timing.system;
                    out.inc_progress();
                }
                _ => {
                    calibration_error = Some(format!(
                        "Could not measure shell execution time. Make sure you can run '{} -c \"\"'.",
                        executor.shell_display()
                    ));
                    break;
                }
            }
        }
        out.finish_progress();
        if let Some(e) = calibration_error {
            return Err(e);
        }
        executor.set_shell_time((sum_real / 50.0, sum_user / 50.0, sum_system / 50.0));
    }

    // --- run benchmarks ---
    let mut results: Vec<BenchmarkResult> = Vec::new();
    for (index, bench) in benchmarks.iter().enumerate() {
        let result = run_benchmark(bench, index, &executor, options_ref, &mut out)?;
        results.push(result);
        export_manager.write_results(&results, sort, time_unit, false)?;
    }

    print_summary(&mut out, &results, sort, has_reference);

    export_manager.write_results(&results, sort, time_unit, true)?;

    Ok(())
}

fn main() {
    ERROR_COLOR.store(colored_default(), AtomicOrdering::Relaxed);
    let matches = build_cli().get_matches();
    if let Err(message) = run(&matches) {
        error_exit(&message);
    }
}
